    void ImportIgnoreFile(Group group){var picker=new OpenFileDialog(){Title="导入忽略文件",Filter="忽略文件|.gitignore;.cursorignore;.cursorindexingignore;.ignore;exclude|文本文件|*.txt|所有文件|*.*"};if(picker.ShowDialog(this)!=true)return;try{string root=Path.GetDirectoryName(picker.FileName);if(Path.GetFileName(picker.FileName)=="exclude"&&Directory.GetParent(root)!=null&&Directory.GetParent(root).Name==".git")root=Directory.GetParent(Directory.GetParent(root).FullName).FullName;var imported=IgnoreFiles.Read(picker.FileName,group==null?"":group.Id,root,false);var w=Ui.Dialog("导入忽略规则",650,600,this);var body=new StackPanel(){Margin=new Thickness(22)};body.Children.Add(Ui.Text(Path.GetFileName(picker.FileName),21,Ui.Ink));body.Children.Add(Ui.Text("范围："+(group==null?"全局":group.Name)+" · 项目："+FilePresentation.FolderName(imported.Root)+" · "+imported.Lines.Count+" 条规则",12,Ui.Muted));body.Children.Add(Ui.Text("保留注释过滤、目录、路径、通配符和 ! 例外的匹配语义。规则以忽略文件所在项目为根目录。",12,Ui.Muted));var rootLabel=Ui.Text("规则根目录："+FilePresentation.FolderName(imported.Root),12,Ui.Muted);body.Children.Add(rootLabel);body.Children.Add(Ui.Button("更改规则根目录",delegate{using(var folderPicker=new System.Windows.Forms.FolderBrowserDialog()){folderPicker.Description="选择此忽略文件要应用的项目目录";if(folderPicker.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;imported.Root=folderPicker.SelectedPath;rootLabel.Text="规则根目录："+FilePresentation.FolderName(imported.Root);}}));var list=new ListBox(){Height=220,ItemsSource=imported.Lines.Take(200),Background=Ui.Surface,Foreground=Ui.Ink};body.Children.Add(list);body.Children.Add(Ui.Button("导入并应用",delegate{controller.Store.Checkpoint();IgnoreFiles.Import(controller.Store.Data,imported);SaveSettings(false);w.Close();ShowSettingsPage("忽略文件");SetStatus("已导入 "+imported.Lines.Count+" 条规则，可停用或撤销。");}));w.Content=body;w.ShowDialog();}catch(Exception ex){Ui.Info("导入未完成："+ex.Message,this);}}
    void EditableIgnoreFileRows(Panel body,Group group,Action rebuild){
        var data=controller.Store.Data;var sets=data.IgnoreFiles.Where(s=>s.ScopeId==(group==null?"":group.Id)).ToArray();
        Section(body,group==null?"全局导入规则":"「"+group.Name+"」导入规则");
        body.Children.Add(Ui.Button("＋ 导入 .gitignore / .cursorignore",delegate{ImportIgnoreFile(group);}));
        foreach(var set in sets){
            var file=set;var container=new StackPanel(){Margin=new Thickness(0,5,0,7)};
            var enabled=new CheckBox(){Content=Path.GetFileName(file.Source)+" · "+FilePresentation.FolderName(file.Root)+" · "+file.Lines.Count+" 条",IsChecked=file.Enabled,Foreground=Ui.Ink};
            enabled.Click+=delegate{controller.Store.Checkpoint();file.Enabled=enabled.IsChecked==true;SaveSettings(false);};container.Children.Add(enabled);
            var list=new ListBox(){Height=106,ItemsSource=file.Lines,Background=Ui.Surface,Foreground=Ui.Ink,Margin=new Thickness(0,3,0,3)};container.Children.Add(list);
            var input=Ui.Input("");input.ToolTip="选择一条规则后编辑；支持 Git 风格通配符和 ! 例外";container.Children.Add(input);
            list.SelectionChanged+=delegate{input.Text=list.SelectedItem as string??"";};
            var actions=new WrapPanel();
            actions.Children.Add(Ui.Button("保存本条",delegate{int index=list.SelectedIndex;if(index<0)return;try{string value=input.Text.Trim();if(value.Length>1024)throw new InvalidDataException("规则最多 1024 字符。");new IgnorePattern(value);controller.Store.Checkpoint();file.Lines[index]=value;file.Automatic=false;file.Revision="manual";SaveSettings(false);list.ItemsSource=null;list.ItemsSource=file.Lines;list.SelectedIndex=index;}catch(Exception ex){Ui.Info(ex.Message,this);}}));
            actions.Children.Add(Ui.Button("＋ 新规则",delegate{if(file.Lines.Count>=2000)return;string value=input.Text.Trim();try{if(value.Length>1024)throw new InvalidDataException("规则最多 1024 字符。");new IgnorePattern(value);controller.Store.Checkpoint();file.Lines.Add(value);file.Automatic=false;file.Revision="manual";SaveSettings(false);list.ItemsSource=null;list.ItemsSource=file.Lines;list.SelectedIndex=file.Lines.Count-1;}catch(Exception ex){Ui.Info(ex.Message,this);}}));
            actions.Children.Add(Ui.Button("移除本条",delegate{int index=list.SelectedIndex;if(index<0)return;controller.Store.Checkpoint();file.Lines.RemoveAt(index);file.Automatic=false;file.Revision="manual";SaveSettings(false);list.ItemsSource=null;list.ItemsSource=file.Lines;list.SelectedIndex=Math.Min(index,file.Lines.Count-1);}));
            actions.Children.Add(Ui.Button("重新读取文件",delegate{try{var incoming=IgnoreFiles.Read(file.Source,file.ScopeId,file.Root,file.Automatic);incoming.Enabled=file.Enabled;controller.Store.Checkpoint();IgnoreFiles.Import(data,incoming);SaveSettings(false);rebuild();}catch(Exception ex){Ui.Info(ex.Message,this);}}));
            actions.Children.Add(Ui.Button(file.Automatic?"停止自动关联":"移除导入",delegate{controller.Store.Checkpoint();if(file.Automatic){file.Automatic=false;file.Enabled=false;file.Revision="manual";}else data.IgnoreFiles.Remove(file);SaveSettings(false);rebuild();}));
            container.Children.Add(actions);
            container.Children.Add(Ui.Text(file.Automatic?"修改后保存为栖桌的独立规则副本。":"栖桌独立规则副本；重新读取会替换此处修改。",11,Ui.Muted));
            body.Children.Add(container);
        }
    }
    StackPanel PluginsPage(){return ComponentLibrary(null,null);}
    public void EditWidget(DesktopWidget widget){var w=Ui.Dialog("设置桌面组件",520,680,this);var body=new StackPanel(){Margin=new Thickness(22)};var plugin=WidgetPlugins.Find(controller.Store.Data,widget.PluginId);body.Children.Add(Ui.Text(plugin==null?"组件":plugin.Name,22,Ui.Ink));body.Children.Add(Ui.Text("标题",12,Ui.Muted));var title=Ui.Input(widget.Name);body.Children.Add(title);var background=Range(body,"背景不透明度",0,1,widget.BackgroundOpacity);var page=Ui.Input((widget.Page+1).ToString());body.Children.Add(Ui.Text("桌面页面",12,Ui.Muted));body.Children.Add(page);var locked=new CheckBox(){Content="锁定位置与大小",IsChecked=widget.Locked,Margin=new Thickness(0,0,0,12)};body.Children.Add(locked);var keep=new CheckBox(){Content="全局隐藏时保留此组件",IsChecked=widget.ExcludeFromHide,Margin=new Thickness(0,0,0,12)};body.Children.Add(keep);var seconds=new CheckBox(){Content="显示秒数",IsChecked=widget.ShowSeconds,Margin=new Thickness(0,0,0,12)};if(plugin!=null&&(plugin.Kind=="clock"||plugin.Kind=="calendar"))body.Children.Add(seconds);var lunar=new CheckBox(){Content="显示农历、节气与节日",IsChecked=widget.ShowLunar,Margin=new Thickness(0,0,0,12)};var calendarClock=new CheckBox(){Content="在日历中显示时钟",IsChecked=widget.ShowCalendarClock,Margin=new Thickness(0,0,0,12)};var monday=new CheckBox(){Content="一周从周一开始",IsChecked=widget.WeekStartMonday,Margin=new Thickness(0,0,0,12)};if(plugin!=null&&plugin.Kind=="calendar"){body.Children.Add(lunar);body.Children.Add(calendarClock);body.Children.Add(monday);}var timeZones=TimeZoneInfo.GetSystemTimeZones().ToArray();var zones=new[]{"local"}.Concat(timeZones.Select(z=>z.Id)).ToArray();var zoneLabels=new[]{"本机时区"}.Concat(timeZones.Select(z=>z.DisplayName)).ToArray();ComboBox zone=null;if(plugin!=null&&plugin.Kind=="clock")zone=Choice(body,"时区",zoneLabels,Array.IndexOf(zones,widget.TimeZone));TextBox text=null;DatePicker target=null;TextBox minutes=null;if(plugin!=null&&plugin.Kind=="focus"){body.Children.Add(Ui.Text("专注时长（1–180 分钟）",12,Ui.Muted));minutes=Ui.Input(widget.FocusMinutes.ToString());body.Children.Add(minutes);}if(plugin!=null&&new[]{"note","tasks","choice","weather","habit","photos","system"}.Contains(plugin.Kind)){text=Ui.Input(widget.Text);if(plugin.Kind=="weather"){body.Children.Add(Ui.Text("城市名称（例如：北京 或 Paris, France）",12,Ui.Muted));body.Children.Add(text);}else if(plugin.Kind=="habit"){body.Children.Add(Ui.Text("习惯名称（例如：喝水 / 每天阅读）",12,Ui.Muted));body.Children.Add(text);}else if(plugin.Kind=="system"){body.Children.Add(Ui.Text("磁盘盘符（例如 C；留空使用系统盘）",12,Ui.Muted));body.Children.Add(text);}else if(plugin.Kind=="photos"){body.Children.Add(Ui.Text("图片文件夹路径",12,Ui.Muted));body.Children.Add(text);body.Children.Add(Ui.Button("选择文件夹",delegate{using(var folderPicker=new System.Windows.Forms.FolderBrowserDialog()){folderPicker.Description="选择要轮播的图片文件夹";if(folderPicker.ShowDialog()==System.Windows.Forms.DialogResult.OK)text.Text=folderPicker.SelectedPath;}}));}else{text.AcceptsReturn=true;text.Height=130;body.Children.Add(Ui.Text("卡片内容",12,Ui.Muted));body.Children.Add(text);}}if(plugin!=null&&plugin.Kind=="countdown"){body.Children.Add(Ui.Text("目标日期",12,Ui.Muted));DateTime date;target=new DatePicker(){SelectedDate=DateTime.TryParse(widget.TargetDate,out date)?date:DateTime.Today.AddDays(7),Margin=new Thickness(0,0,0,12)};body.Children.Add(target);}
        var color=Ui.Input(widget.Color);body.Children.Add(Ui.Text("组件强调色",12,Ui.Muted));body.Children.Add(color);var corners=Choice(body,"组件边角",new[]{"圆角","方角"},widget.CornerStyle=="方角"?1:0);var border=Range(body,"边框与手柄不透明度",0,1,widget.BorderOpacity);
        body.Children.Add(Ui.Button("保存",delegate{int n;if(String.IsNullOrWhiteSpace(title.Text)||title.Text.Length>80||!Int32.TryParse(page.Text,out n)||n<1||n>20){Ui.Info("标题应为 1–80 字符，页面为 1–20。",w);return;}int durationValue=widget.FocusMinutes;if(minutes!=null&&(!Int32.TryParse(minutes.Text,out durationValue)||durationValue<1||durationValue>180)){Ui.Info("专注时长应为 1–180 分钟。",w);return;}if(text!=null&&text.Text.Length>2000){Ui.Info("组件内容最多 2000 字符。",w);return;}try{ColorConverter.ConvertFromString(color.Text);}catch{Ui.Info("组件颜色格式不正确。",w);return;}controller.Store.Checkpoint();widget.Name=title.Text.Trim();widget.BackgroundOpacity=background.Value;widget.BorderOpacity=border.Value;widget.Color=color.Text.Trim();widget.CornerStyle=Convert.ToString(corners.SelectedItem);widget.Page=n-1;controller.Store.Data.Pages=Math.Max(n,controller.Store.Data.Pages);widget.Locked=locked.IsChecked==true;widget.ExcludeFromHide=keep.IsChecked==true;widget.ShowSeconds=seconds.IsChecked==true;widget.ShowLunar=lunar.IsChecked==true;widget.ShowCalendarClock=calendarClock.IsChecked==true;widget.WeekStartMonday=monday.IsChecked==true;if(zone!=null)widget.TimeZone=zones[zone.SelectedIndex];if(text!=null&&widget.Text!=text.Text){widget.Text=text.Text;widget.CheckedTasks.Clear();}if(minutes!=null&&widget.FocusMinutes!=durationValue){widget.FocusMinutes=durationValue;widget.FocusUntil="";widget.FocusPausedSeconds=0;}if(target!=null&&target.SelectedDate.HasValue)widget.TargetDate=target.SelectedDate.Value.ToString("yyyy-MM-dd");SaveSettings(true);w.Close();if(CurrentSettingsPage=="插件与组件")ShowSettingsPage(CurrentSettingsPage);}));w.Content=new ScrollViewer(){Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};w.ShowDialog();}
}
